def solve_game(N):
    """
    Determines if N is Type A (A wins) or Type B (B wins).
    Returns True if Type A, False if Type B.
    """
    if N <= 1:
        return False # Edge case, though problem states N is positive integer >= 1.

    # Win[i] is True if the player whose turn it is at number i has a winning strategy.
    # We calculate backwards from N-1 down to 1.
    Win = {}

    for n in range(N - 1, 0, -1):
        winning_move_exists = False

        moves = []
        # Move +1
        if n + 1 <= N:
            moves.append(n + 1)
        # Move *2
        if 2 * n <= N:
            moves.append(2 * n)

        # Check for immediate win (move lands exactly on N)
        if N in moves:
            Win[n] = True
            continue

        # Check for subsequent moves leading to a losing position for the opponent
        for next_n in moves:
            if next_n < N:
                # The opponent receives next_n. We win if the opponent loses from next_n.
                # Since we are calculating backwards, Win[next_n] must already be defined.
                if not Win[next_n]:
                    winning_move_exists = True
                    break

        Win[n] = winning_move_exists

    # N is Type A if A (starting at 1) wins.
    return Win[1]

